    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_pow_12(n):
    if n == 1:
        # n=1, n^12=1. tau(1) = 1.
        return 1

    factors = prime_factorization(n)
    tau_val = 1
    for p, e in factors.items():
        # The exponent in n^12 is 12 * e
        exponent_n_pow_12 = 12 * e
        # The factor in tau is (exponent + 1)
        tau_val *= (exponent_n_pow_12 + 1)
    return tau_val

